n":"Birds and birdwatching","l3":["Bird identification","Migration","Bird intelligence","Backyard birds","Birdsong","Birding trips","Bird conservation"]},{"n":"Oceans","l3":["Deep-sea life","Coral reefs","Ocean exploration","Sharks","Ocean conservation","Shipwrecks","Tides and currents"]},{"n":"Climate change","l3":["Climate science","Extreme weather","Climate solutions","Clean energy","Climate and health","Carbon removal","Climate policy"]},{"n":"Conservation","l3":["Rewilding","Protected lands","Conservation success stories","Invasive species","Wildlife corridors","Zoos and sanctuaries","Indigenous land stewardship"]},{"n":"Plants and fungi","l3":["Trees and forests","Mushrooms and fungi","Plant intelligence","Wildflowers","Foraging","Rare plants","Seeds and seed saving"]}]}]$tax$::jsonb j),
l1 as (
  select a->>'n' label, a->>'d' descr, private.slugify(a->>'n') slug, a
  from tax, jsonb_array_elements(j) a
),
l2 as (
  select b->>'n' label, l1.slug || '--' || private.slugify(b->>'n') slug, l1.slug parent_slug, b
  from l1, jsonb_array_elements(l1.a->'l2') b
),
l3 as (
  select c label, l2.slug || '--' || private.slugify(c) slug, l2.slug parent_slug
  from l2, jsonb_array_elements_text(l2.b->'l3') c
),
allrows as (
  select slug, label, 1 lvl, null::text parent_slug, descr from l1
  union all select slug, label, 2, parent_slug, null from l2
  union all select slug, label, 3, parent_slug, null from l3
)
insert into public.topics (id, slug, label, level, parent_id, description)
select md5(slug)::uuid, slug, label, lvl, case when parent_slug is not null then md5(parent_slug)::uuid end, descr
from allrows order by lvl
on conflict (slug) do update set label = excluded.label, level = excluded.level,
  parent_id = excluded.parent_id, description = coalesce(excluded.description, public.topics.description);

-- When a tag matches a label used in more than one place (e.g. "Watches"), pick consistently:
-- a topic this user already uses, else the most specific level, else alphabetical by path.
create or replace function private.resolve_topic(p_label text, p_uid uuid, out topic_id uuid, out label text, out created boolean)
language plpgsql security definer set search_path = '' as $$
declare v_slug text := private.slugify(p_label);
begin
  created := false;
  select t.id, t.label into topic_id, label from public.topics t
   where lower(t.label) = lower(trim(p_label)) or t.slug = v_slug
   order by exists (select 1 from public.disco_topics dt where dt.topic_id = t.id and dt.user_id = p_uid) desc,
            t.level desc nulls first, t.slug
   limit 1;
  if topic_id is null then
    select t.id, t.label into topic_id, label from public.topic_aliases a
      join public.topics t on t.id = a.topic_id
     where lower(a.alias) = lower(trim(p_label)) limit 1;
  end if;
  if topic_id is null then
    if v_slug = '' then v_slug := 'topic-' || substr(md5(p_label), 1, 8); end if;
    insert into public.topics (slug, label, created_by) values (v_slug, trim(p_label), p_uid)
      on conflict (slug) do nothing
      returning id, topics.label into topic_id, label;
    if topic_id is null then
      select t.id, t.label into topic_id, label from public.topics t where t.slug = v_slug;
    else
      created := true;
    end if;
  end if;
end;
$$;
revoke all on function private.resolve_topic(text, uuid) from public, anon, authenticated;
